import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1960年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1960年/核心总结.md","filePath":"01_letters/1960年/核心总结.md"}'),n={name:"01_letters/1960年/核心总结.md"};function l(i,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1960年-核心总结" tabindex="-1">1960年 核心总结 <a class="header-anchor" href="#_1960年-核心总结" aria-label="Permalink to &quot;1960年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1960年道琼斯指数下跌9.3%，市场一片惨淡。然而，巴菲特合伙企业逆势上扬，取得了+22.8%的惊人回报。这一年对合伙企业而言是具有里程碑意义的一年：合伙企业总数从5个增加到7个，业务架构日趋成熟。值得注意的是，即便在指数下跌近10%的年份，合伙企业依然大幅跑赢市场，验证了巴菲特早期价值投资策略的有效性。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>本年的标志性案例是桑博恩地图公司（Sanborn Map Company）。巴菲特在该公司上投入了合伙企业资产的35%——这是一个极为集中的仓位。核心逻辑在于：桑博恩公司的内在价值约为每股135美元，而市场交易价格仅约45美元，价值与价格之间存在巨大鸿沟。这种&quot;烟蒂股&quot;策略是巴菲特早期的核心投资方法——找到市场价格显著低于内在价值的标的，重仓持有，等待价值回归。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特在信中强调，市场短期波动是正常的，但内在价值的增长最终会反映在股价上。他对桑博恩地图的投资充分体现了这一理念：当市场价格远低于企业价值时，分散投资反而会拉低回报率，集中持仓是合理的策略。这一时期的巴菲特更接近格雷厄姆的&quot;捡烟蒂&quot;哲学。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>本杰明·格雷厄姆的影响依然深刻体现在巴菲特的投资框架中。虽然格雷厄姆此时已淡出日常管理，但他的价值投资方法论是巴菲特早年的行动指南。桑博恩地图公司的管理层也在这一年的合作中扮演了重要角色。</p>',9)])])}const u=e(n,[["render",l]]);export{p as __pageData,u as default};
